parameters.jsCode:
// [COMPANY_NAME] – F7 – موضوعات المحتوى التلقائية
const now = new Date();
const day = now.getDay();
const month = now.getMonth() + 1;

const dayTopics = {
  0: [ // الأحد – أتمتة الأعمال
    { topic: 'كيف تُحوّل عملك بـ n8n والأتمتة الذكية', type: 'educational', angle: 'automation_intro' },
    { topic: 'ربط واتساب مع CRM تلقائياً – دليل عملي', type: 'tutorial', angle: 'wa_crm' },
  ],
  1: [ // الاثنين – الذكاء الاصطناعي
    { topic: 'كيف يُساعدك ChatGPT في أعمالك اليومية', type: 'educational', angle: 'ai_business' },
    { topic: 'أدوات الذكاء الاصطناعي للشركات الصغيرة 2026', type: 'list', angle: 'ai_tools' },
  ],
  2: [ // الثلاثاء – التصميم والجرافيك
    { topic: 'أهمية الهوية البصرية لنجاح علامتك التجارية', type: 'educational', angle: 'branding' },
    { topic: 'تجارب عملائنا في التصميم – قصص نجاح حقيقية', type: 'testimonial', angle: 'design_cases' },
  ],
  3: [ // الأربعاء – المواقع وSEO
    { topic: 'لماذا تحتاج موقعاً احترافياً في 2026؟', type: 'promotional', angle: 'web_importance' },
    { topic: 'أسرار تصدر نتائج البحث في السوق السعودي', type: 'educational', angle: 'seo_ksa' },
  ],
  4: [ // الخميس – التسويق والمحتوى
    { topic: 'استراتيجية المحتوى للشركات السعودية 2026', type: 'educational', angle: 'content_strategy' },
    { topic: 'كيف تُدير حسابات السوشيال ميديا باحتراف', type: 'tutorial', angle: 'social_mgmt' },
  ],
  5: [ // الجمعة – دعوات المناسبة خاصة والمناسبات
    { topic: 'ثورة دعوات المناسبة خاصة الرقمية في المملكة', type: 'promotional', angle: 'special_service_digital' },
    { topic: 'باقات الدعوات الرقمية من [COMPANY_NAME] – رقي وحداثة', type: 'showcase', angle: 'special_service_packages' },
  ],
  6: [ // السبت – التدريب والعروض
    { topic: 'تعلم n8n وابدأ رحلة الأتمتة الاحترافية', type: 'training', angle: 'n8n_course' },
    { topic: 'عرض خاص: حلول الأتمتة الشاملة لشركتك', type: 'promotional', angle: 'weekend_offer' },
  ],
};

const seasonalBonus = [];
if (month >= 9 && month <= 11) { // موسم الأعراس
  seasonalBonus.push({ topic: 'موسم الأعراس 2026 – دعوتك الرقمية تستحق التميز', type: 'seasonal', angle: 'special_service_season' });
}
if (month === 1) { // بداية السنة
  seasonalBonus.push({ topic: 'خطط لعام أتمتة ناجح مع [COMPANY_NAME]', type: 'seasonal', angle: 'new_year' });
}

const todayTopics = [...(dayTopics[day] || dayTopics[0]), ...seasonalBonus];
const POSTS_PER_DAY = 2;
const selectedTopics = todayTopics.slice(0, POSTS_PER_DAY);

return selectedTopics.map((t, i) => ({
  json: {
    ...t,
    topic_id: `[COMPANY_NAME]-${new Date().toISOString().split('T')[0].replace(/-/g,'')}-${String(i+1).padStart(2,'0')}`,
    company_name:  '[COMPANY_NAME]',
    company_url:   'https://[COMPANY_NAME].sa',
    whatsapp:      'https://[YOUR_WHATSAPP_LINK]',
    service_link:  'https://[COMPANY_NAME].sa/services',
    day_index:     day,
    generated_at:  new Date().toISOString(),
  }
}));

const original = $('Split – موضوع واحد في المرة').first().json;
const aiRaw    = $input.first().json;

let rawText = '';
if (typeof aiRaw === 'string') rawText = aiRaw;
else if (aiRaw?.text) rawText = aiRaw.text;
else if (aiRaw?.content?.[0]?.text) rawText = aiRaw.content[0].text;
else if (aiRaw?.output) rawText = aiRaw.output;
else rawText = JSON.stringify(aiRaw);

let parsed = {};
try {
  const cleaned = rawText
    .replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch(e) {
  const topic = original.topic || '[COMPANY_NAME] للأتمتة';
  const link = original.company_context?.order_link || '[YOUR_WHATSAPP_LINK]';
  parsed = {
    ar_title: topic,
    ar_body: `نحن متخصصون في تقديم أفضل تجارب الخدمة في العراق. ${topic}`,
    x_post: `🏢 ${topic} | اطلب الآن! #خدمات_عامة #2026 #QualityService`,
    instagram_post: `🏢 ${topic}\n\n✅ قريب من المركز\n✅ أسعار مميزة\n📞 اطلب الآن!\n#خدمات_عامة #العراق #2026 #2026 #QualityService`,
    facebook_post: `${topic}\n\nنحن هنا لمساعدتك في اختيار أفضل خدمة في العراق. اكتب لنا في التعليقات! 👇`,
    whatsapp_broadcast: `السلام عليكم ✨\n\n${topic}\n\nللطلب وللاستفسار:\n${link}`,
    telegram_post: `🏢 ${topic}\n\nاطلب الآن: ${link}`,
    tiktok_caption: `${topic} 🏢 #خدمات_عامة #2026 #العراق #QualityService #service2026`,
    image_prompt_en: `Professional business environment, golden hour, professional photography, 16:9`,
    image_prompt_ar: 'مقر احترافي بإطلالة مميزة',
    template_text_ar: topic.substring(0, 35),
    template_subtext_ar: link,
    best_posting_time: '18:00',
    content_score: 70,
    target_emotion: 'trust',
    cta: 'اطلب الآن وتمتع بأفضل الأسعار'
  };
}

const now = new Date().toISOString();
const dateStr = now.split('T')[0];
const rowNum = Date.now(); // unique row ID

const baseHashtags = '#خدمات_عامة #طلب_خدمة_عامة #2026 #2026 #QualityService #service_2026 #ServiceQuality #العراق';

return [{
  json: {
    row_number:          rowNum,
    topic_id:            original.topic_id,
    topic:               original.topic,
    content_type:        original.content_type,
    angle:               original.angle,

    ar_title:            parsed.ar_title    || original.topic,
    ar_body:             parsed.ar_body     || '',
    target_emotion:      parsed.target_emotion || 'trust',
    cta:                 parsed.cta         || 'اطلب الآن',

    x_post:              (parsed.x_post             || '').substring(0, 270),
    instagram_post:      parsed.instagram_post       || '',
    facebook_post:       parsed.facebook_post        || '',
    whatsapp_broadcast:  parsed.whatsapp_broadcast   || '',
    telegram_post:       parsed.telegram_post        || '',
    tiktok_caption:      (parsed.tiktok_caption      || '').substring(0, 200),
    seo_hashtags:        baseHashtags,

    image_prompt_ar:     parsed.image_prompt_ar     || '',
    image_prompt_en:     parsed.image_prompt_en     || '',
    template_text_ar:    parsed.template_text_ar    || '',
    template_subtext_ar: parsed.template_subtext_ar || '',
    image_status:        'pending',        // سيُحدَّث بـ F8 بعد توليد الصورة
    image_url:           '',               // سيُملأ بـ F8

    content_score:       parseInt(parsed.content_score || 70),
    best_posting_time:   parsed.best_posting_time || '18:00',
    platforms:           (original.platforms || []).join(','),

    status:              'ready_to_publish',  // F8 يسحب هذه الحالة
    generated_at:        now,
    published_at:        '',
    published_on:        '',
    publish_attempts:    0,

    company_name:    original.company_context?.name    || '',
    order_link:  original.company_context?.order_link || '',
    company_phone:   original.company_context?.phone   || '',
  }
}];

